python - <<'PY'
from semver import VersionInfo

for version in (VersionInfo(1, 2, 3), VersionInfo(1, 2, 3, 'rc.1', 'build.2')):
    expected = (version.major, version.minor, version.patch, version.prerelease, version.build)
    assert isinstance(version.to_tuple(), tuple)
    assert version.to_tuple() == expected
    assert isinstance(version.to_dict(), dict)
    assert version.to_dict() == dict(zip(('major', 'minor', 'patch', 'prerelease', 'build'), expected))
    for index in range(-5, 5):
        assert version[index] == expected[index]
    for start in (None, -8, -1, 0, 2, 5, 8):
        for stop in (None, -8, -1, 0, 2, 5, 8):
            for step in (None, -2, -1, 1, 2):
                key = slice(start, stop, step)
                assert version[key] == expected[key]
    for key, error in ((5, IndexError), (-6, IndexError), ('major', TypeError), (1.0, TypeError), (slice(None, None, 0), ValueError)):
        try:
            version[key]
        except error:
            pass
        else:
            raise AssertionError('Expected %s for %r' % (error, key))
    parts = version.to_dict()
    parts['major'] = 99
    assert version.major == 1
print('Public accessors and tuple-style indexing checks passed.')
PY
